template:
% 参数由系统自动注入：\def\focusparam{1.2} \def\orientation{right} \def\showvertex{1} \def\showaxis{1} \def\showfocus{1} \def\showdirectrix{1} \def\showpoint{0} \def\pointy{1.8} \def\pointx{1.5} \def\labelp{P}
% 焦点到顶点距离 = p/2
\pgfmathsetmacro{\halfp}{\focusparam/2}
% 开口向右：y^2 = 2px，点 P 的 x = y^2/(2p)；准线 x = -p/2，对称轴为 x 轴
\pgfmathsetmacro{\Px}{\pointy*\pointy/(2*\focusparam)}
\pgfmathsetmacro{\Pxm}{-\halfp}
% 开口向上：x^2 = 2py，点 P 的 y = x^2/(2p)；准线 y = -p/2，对称轴为 y 轴
\pgfmathsetmacro{\Py}{\pointx*\pointx/(2*\focusparam)}
\pgfmathsetmacro{\Pym}{-\halfp}
% 视图范围：向右的 x 视图，取点横坐标与焦点的较大值再留余量
\pgfmathsetmacro{\vright}{max(1.3*\Px, 1.2*\halfp, 2.5) + 0.8}
\pgfmathsetmacro{\vup}{max(1.3*\pointy, 1.2*\halfp, 2.0) + 0.8}
% 视觉归一化
\pgfmathsetmacro{\figscale}{6 / max(\vright + \halfp + 0.8, 2.0)}
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\pgfmathsetmacro{\loff}{0.34/\figscale}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \ifnum\strcmp{\orientation}{right}=0
    % 开口向右 y^2=2px：焦点 F(p/2,0)，准线 x=-p/2
    \coordinate (V) at (0,0);
    \coordinate (F) at (\halfp,0);
    % 对称轴（x 轴）
    \ifnum\showaxis>0
      \draw[dashed, gray] (-\halfp-0.3,0) -- (\vright,0);
    \fi
    % 抛物线曲线：x = y^2/(2p)，纵坐标从 -vup 到 vup
    \draw[thick, domain=-\vup:\vup, samples=80, smooth] plot ({\x*\x/(2*\focusparam)},{\x});
    % 抛物线上点 P 连焦点与准线垂足 M
    \ifnum\showpoint>0
      \draw[thick] (F) -- (\Px,\pointy) -- (\Pxm,\pointy);
      \fill (\Px,\pointy) circle [radius=\dotr pt];
      \fill (\Pxm,\pointy) circle [radius=\dotr pt];
      \node at ({1.12*\Px},{1.12*\pointy}) {$\labelp$};
      \node[left=2pt] at (\Pxm,\pointy) {$M$};
    \fi
    % 焦点 F
    \ifnum\showfocus>0
      \fill (F) circle [radius=\dotr pt];
      \node[above right=2pt] at (F) {$F$};
    \fi
    % 准线 l：x = -p/2
    \ifnum\showdirectrix>0
      \draw[thick] (\Pxm,-\vup) -- (\Pxm,\vup);
      \node[left=2pt] at (\Pxm,\vup) {$l$};
    \fi
  \else
    % 开口向上 x^2=2py：焦点 F(0,p/2)，准线 y=-p/2
    \coordinate (V) at (0,0);
    \coordinate (F) at (0,\halfp);
    % 对称轴（y 轴）
    \ifnum\showaxis>0
      \draw[dashed, gray] (0,-\halfp-0.3) -- (0,\vup);
    \fi
    % 抛物线曲线：y = x^2/(2p)，横坐标从 -vright 到 vright
    \draw[thick, domain=-\vright:\vright, samples=80, smooth] plot ({\x},{\x*\x/(2*\focusparam)});
    % 抛物线上点 P 连焦点与准线垂足 M
    \ifnum\showpoint>0
      \draw[thick] (F) -- (\pointx,\Py) -- (\pointx,\Pym);
      \fill (\pointx,\Py) circle [radius=\dotr pt];
      \fill (\pointx,\Pym) circle [radius=\dotr pt];
      \node at ({1.12*\pointx},{1.12*\Py}) {$\labelp$};
      \node[below=2pt] at (\pointx,\Pym) {$M$};
    \fi
    % 焦点 F
    \ifnum\showfocus>0
      \fill (F) circle [radius=\dotr pt];
      \node[right=2pt] at (F) {$F$};
    \fi
    % 准线 l：y = -p/2
    \ifnum\showdirectrix>0
      \draw[thick] (-\vright,\Pym) -- (\vright,\Pym);
      \node[right=2pt] at (-\vright,\Pym) {$l$};
    \fi
  \fi
  % 顶点 O
  \ifnum\showvertex>0
    \fill (V) circle [radius=\dotr pt];
    \node[below left=2pt] at (V) {$O$};
  \fi
\end{tikzpicture}
